// ===== Build : ตรวจภาพ 2 ภาพ + ประกอบคำขอ "ถอดความทีละภาพ" (v2) =====
// แอป (artwork_check/pairdiff.py) ส่ง POST form-urlencoded 2 ฟิลด์:
//   image_a_b64 = ภาพโซนของไฟล์หลัก (🅰) · image_b_b64 = ภาพโซนของไฟล์อ้างอิง (🅱)
//
// 🔑 v2 (30 ก.ย.): ถอดความ **แยกคำขอ ภาพละ 1 คำขอ** — v1 ส่งสองภาพในคำขอเดียว
// แล้ว Gemini เขียนข้อความชุดเดียวให้ทั้งสองฝั่ง (ทดสอบจริง AvoDerm โซนใหญ่:
// กลืนความต่างจริง 4/4 จุด ทั้งที่ prompt สั่ง "NEVER copy") ⇒ คำขอถอดความ
// **เห็นภาพเดียวเท่านั้น** จึงลอกอีกฝั่งไม่ได้โดยโครงสร้าง ไม่ใช่โดยคำสั่ง
// ขั้นเทียบ (คำขอที่ 3) เห็นทั้งสองภาพ แต่ **ห้ามแก้ข้อความที่ถอดแล้ว**

const item = $input.first().json;
const body = item.body ?? item;

function clean(v) {
  let b64 = String(v ?? '').trim();
  const m = b64.match(/^data:image\/[a-z0-9.+-]+;base64,(.+)$/is);
  if (m) b64 = m[1];
  return b64.replace(/\s+/g, '').replace(/ /g, '+');
}
function mimeOf(b64) {
  const h = Buffer.from(b64.slice(0, 32), 'base64');
  if (h[0] === 0x89 && h[1] === 0x50 && h[2] === 0x4e) return 'image/png';
  if (h[0] === 0xff && h[1] === 0xd8) return 'image/jpeg';
  if (h[0] === 0x52 && h[1] === 0x49 && h[2] === 0x46 && h[8] === 0x57 && h[9] === 0x45) return 'image/webp';
  return null;
}

const a = clean(body.image_a_b64);
const b = clean(body.image_b_b64);
let valid = true;
let error = '';
const re64 = /^[A-Za-z0-9+/]+={0,2}$/;
for (const [name, v] of [['image_a_b64', a], ['image_b_b64', b]]) {
  if (!v) { valid = false; error = `missing form field '${name}'`; break; }
  if (v.length % 4 !== 0 || !re64.test(v)) { valid = false; error = `'${name}' is not valid base64`; break; }
}
const mimeA = valid ? mimeOf(a) : null;
const mimeB = valid ? mimeOf(b) : null;
if (valid && (!mimeA || !mimeB)) { valid = false; error = 'unsupported image format (expected JPEG / PNG / WebP)'; }
const sizeBytes = Math.floor((a.length + b.length) * 3 / 4);
if (valid && sizeBytes > 19 * 1024 * 1024) {
  valid = false;
  error = `images too large: ${(sizeBytes / 1048576).toFixed(1)} MB (limit ~19 MB)`;
}

const TRANSCRIBE = "Transcribe ALL text printed in this label image, VERBATIM.\n" +
  "- This is quality control: the text may contain real printing mistakes. Copy exactly what is printed.\n" +
  "  DO NOT correct spelling, grammar, capitalization, punctuation, digits or units.\n" +
  "- Preserve letter case exactly (e.g. \"D-calcium\" stays \"D-calcium\"), decimal points, minus signs,\n" +
  "  <, >, %, superscripts and symbols (e.g. \"0.5g\", \"<1g\", \"-18°C\", \"®\").\n" +
  "- One printed line per output line, reading order top-to-bottom, left-to-right.\n" +
  "- Write any run of leader dots (......) as exactly three dots \"...\".\n" +
  "- Text on curves/badges: transcribe it when legible. Skip what you cannot read; never guess.\n" +
  "- Output ONLY the transcription, no comments, no markdown.";

function transcribeRequest(mime, data) {
  return {
    contents: [{ role: 'user', parts: [
      { text: TRANSCRIBE },
      { inlineData: { mimeType: mime, data } },   // ⚠️ ภาพเดียวเท่านั้น
    ] }],
    generationConfig: {
      temperature: 0,          // ห้ามแก้ — ต้องวัดซ้ำได้
      topP: 1,
      maxOutputTokens: 8192,   // เพดานกันวนพิมพ์ซ้ำไม่จบ (เคย 21,378 ตัวอักษร)
      thinkingConfig: { thinkingBudget: 0 },
    },
  };
}

return [{ json: {
  valid, error,
  size_kb: Math.round(sizeBytes / 102.4) / 10,
  img: valid ? { a, b, mimeA, mimeB } : null,
  req_a: valid ? transcribeRequest(mimeA, a) : null,
  req_b: valid ? transcribeRequest(mimeB, b) : null,
} }];

// ===== Split : แตกเป็น 2 item (ภาพ 🅰 · ภาพ 🅱) → HTTP ถอดความทีละภาพ =====
const j = $input.first().json;
return [
  { json: { side: 'a', gemini_request: j.req_a } },
  { json: { side: 'b', gemini_request: j.req_b } },
];

// ===== Collect : รวมข้อความที่ถอด "แยกกัน" + ประกอบคำขอเทียบ (เห็นสองภาพ) =====
function textOf(r) {
  if (!r || r.error) return { text: '', why: `Gemini API error: ${JSON.stringify((r || {}).error || 'no response')}` };
  const cand = (r.candidates ?? [])[0] ?? {};
  const text = ((cand.content ?? {}).parts ?? []).filter((p) => !p.thought)
    .map((p) => p.text ?? '').join('\n').trim()
    .replace(/^```[a-z]*\s*/i, '').replace(/\s*```$/, '').trim();
  const fr = cand.finishReason ?? '';
  return { text, why: fr && fr !== 'STOP' ? `finishReason=${fr}` : '' };
}
const items = $input.all();
const ra = textOf(items[0] && items[0].json);
const rb = textOf(items[1] && items[1].json);
const img = $('Build').first().json.img;

const COMPARE = "IMAGE A is the approved artwork. IMAGE B is the version to check.\n" +
  "Each image was transcribed SEPARATELY (A_TEXT, B_TEXT below). The transcriptions are final:\n" +
  "do NOT rewrite them. They may contain reading errors.\n\n" +
  "List the differences in what is actually PRINTED on A versus B:\n" +
  "- Go through every place where A_TEXT and B_TEXT differ. Look at BOTH images at that spot.\n" +
  "  Report it only if the printed text really differs (a real difference can be a single letter,\n" +
  "  letter case, a digit, a decimal point, a sign, or a missing/extra word). If it is only a\n" +
  "  reading error of the transcription, do not report it.\n" +
  "- \"a\" and \"b\": copy the differing span EXACTLY from A_TEXT and B_TEXT (shortest span that\n" +
  "  shows the difference). Use \"\" when the text is absent on that side.\n" +
  "- Also report print differences the transcriptions missed: if you can quote them from A_TEXT /\n" +
  "  B_TEXT do so; otherwise use kind \"visual\" with a=\"\" b=\"\" and describe it in \"where\".\n" +
  "- kind: \"number\" (digits/units/decimals/signs), \"text\" (words/letters/case/punctuation),\n" +
  "  \"visual\" (font weight, colour, logo, symbol, barcode bars, layout).\n" +
  "- Ignore line wrapping, image quality, glare, perspective and anything outside the label panel.\n" +
  "- If nothing printed differs, return an empty array.\n\nReturn ONLY JSON matching the schema.";

const responseSchema = {
  type: 'OBJECT',
  properties: {
    differences: {
      type: 'ARRAY',
      items: {
        type: 'OBJECT',
        properties: {
          a: { type: 'STRING' }, b: { type: 'STRING' },
          kind: { type: 'STRING', enum: ['text', 'number', 'visual'] },
          where: { type: 'STRING' },
        },
        required: ['a', 'b', 'kind'],
      },
    },
  },
  required: ['differences'],
};

const ok = !!(ra.text && rb.text);
return [{ json: {
  a_text: ra.text, b_text: rb.text, ok,
  error: ok ? '' : `transcription failed (A: ${ra.why || (ra.text ? 'ok' : 'empty')} · B: ${rb.why || (rb.text ? 'ok' : 'empty')})`,
  warning: [ra.why && `A ${ra.why}`, rb.why && `B ${rb.why}`].filter(Boolean).join(' · '),
  gemini_request: !ok ? null : {
    contents: [{ role: 'user', parts: [
      { text: COMPARE },
      { text: 'IMAGE A (approved artwork):' }, { inlineData: { mimeType: img.mimeA, data: img.a } },
      { text: 'IMAGE B (version to check):' }, { inlineData: { mimeType: img.mimeB, data: img.b } },
      { text: 'A_TEXT:\n' + ra.text }, { text: 'B_TEXT:\n' + rb.text },
    ] }],
    generationConfig: {
      temperature: 0, topP: 1, maxOutputTokens: 8192,
      responseMimeType: 'application/json', responseSchema,
      thinkingConfig: { thinkingBudget: 1024 },
    },
  },
} }];

// ===== Parse : ผลเทียบ → สัญญาของแอป =====
// a_text / b_text มาจาก **การถอดแยกคำขอ** (Collect) เสมอ — ขั้นเทียบแก้ไม่ได้
// ขั้นเทียบล้ม = ส่งข้อความทั้งสองฝั่งกลับพร้อม differences ว่าง + warning
// (แอปจะใช้ชั้นเทียบข้อความบนข้อความที่ถอดแยก แล้วลดรายการที่ Gemini ไม่ยืนยัน
//  เป็น REVIEW — ไม่มีทางกลายเป็น PASS เงียบ ๆ)
const c = $('Collect').first().json;
const r = $input.first().json || {};
const out = { a_text: c.a_text, b_text: c.b_text, differences: [],
              engine: 'gemini-2.5-flash', warning: c.warning || '' };
if (!c.ok) {
  out.error = c.error;
  return [{ json: out }];
}
const warn = [];
if (c.warning) warn.push(c.warning);
if (r.error) {
  warn.push(`compare step failed: ${JSON.stringify(r.error).slice(0, 200)}`);
} else {
  const cand = (r.candidates ?? [])[0] ?? {};
  const raw = ((cand.content ?? {}).parts ?? []).filter((p) => !p.thought)
    .map((p) => p.text ?? '').join('\n').trim();
  let s = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
  let parsed = null;
  try { parsed = JSON.parse(s); } catch (e) {
    const i = s.indexOf('{'); const j = s.lastIndexOf('}');
    if (i >= 0 && j > i) { try { parsed = JSON.parse(s.slice(i, j + 1)); } catch (e2) { /* noop */ } }
  }
  if (parsed && Array.isArray(parsed.differences)) out.differences = parsed.differences;
  else warn.push('compare step returned no parsable differences');
  const fr = cand.finishReason ?? '';
  if (fr && fr !== 'STOP') warn.push(`compare finishReason=${fr}`);
}
out.warning = warn.join(' · ');
return [{ json: out }];
